<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= htmlspecialchars($appName, ENT_QUOTES, 'UTF-8') ?> — Members</title><link rel="stylesheet" href="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/assets/app.css"></head>
<body>
<header class="app-header"><p class="brand">ZPM Membership Management</p><div class="user-menu"><span><?= htmlspecialchars($user['full_name'], ENT_QUOTES, 'UTF-8') ?></span><form method="post" action="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/logout"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><button class="logout" type="submit">Sign out</button></form></div></header>
<div class="layout"><?php require __DIR__ . '/partials/nav.php'; ?>
<main class="main"><div class="section-heading"><h1>Member register</h1><?php if ($user !== null): ?><a class="button-link primary-link" href="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/members/new">Add member</a><?php endif; ?></div>
<section class="content-card"><form class="filter-grid" method="get"><div class="field"><label for="q">Search name or member code</label><input id="q" name="q" value="<?= htmlspecialchars($memberFilters['q'], ENT_QUOTES, 'UTF-8') ?>"></div><div class="field"><label for="status">Status</label><select id="status" name="status"><option value="">All statuses</option><?php foreach (['active','inactive','resigned','deceased','archived'] as $status): ?><option value="<?= $status ?>" <?= $memberFilters['status'] === $status ? 'selected' : '' ?>><?= ucfirst($status) ?></option><?php endforeach; ?></select></div><div class="filter-actions"><button type="submit">Search</button><a class="button-link" href="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/members">Clear</a></div></form><p class="muted"><?= number_format($memberTotal) ?> records; showing page <?= (int) $memberFilters['page'] ?> of <?= (int) $memberPages ?>.</p><div class="table-wrap"><table class="member-table"><thead><tr><th>Code</th><th>Name</th><th>Status</th><th>District</th><th>Block</th><th>Unit</th><th>Enrollment</th><th>Actions</th></tr></thead><tbody><?php foreach ($memberRows as $row): ?><tr><td><?= htmlspecialchars($row['member_code'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['full_name'], ENT_QUOTES, 'UTF-8') ?></td><td><span class="status-badge status-<?= htmlspecialchars($row['membership_status'], ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars(ucfirst($row['membership_status']), ENT_QUOTES, 'UTF-8') ?></span></td><td><?= htmlspecialchars($row['district_name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['block_name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['unit_name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['enrollment_date'], ENT_QUOTES, 'UTF-8') ?></td><td><a href="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/members/<?= (int) $row['id'] ?>/edit">Edit</a><?php if ($row['membership_status'] !== 'archived'): ?><form class="inline-form" method="post" action="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/members/<?= (int) $row['id'] ?>/archive" data-confirm="Archive this member?"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><button class="link-button" type="submit">Archive</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php if ($memberPages > 1): ?><nav class="pagination" aria-label="Member register pages"><?php if ($memberFilters['page'] > 1): ?><a class="button-link" href="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/members?<?= http_build_query(array_merge($memberFilters, ['page' => $memberFilters['page'] - 1])) ?>">Previous</a><?php endif; ?><span>Page <?= (int) $memberFilters['page'] ?> of <?= (int) $memberPages ?></span><?php if ($memberFilters['page'] < $memberPages): ?><a class="button-link" href="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/members?<?= http_build_query(array_merge($memberFilters, ['page' => $memberFilters['page'] + 1])) ?>">Next</a><?php endif; ?></nav><?php endif; ?></section></main></div><script src="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/assets/app.js"></script></body></html>
